def translate(value, language):
    if language != "en":return value
    if value in SYSTEM_EN:return SYSTEM_EN[value]
    from dinas import META,NUMBERS,FIELDS
    for _,label,english,*_ in [*META,*NUMBERS,*FIELDS]:
        if value==label+' maksimal 150 karakter.':return english+' must not exceed 150 characters.'
        if value==label+' harus berupa angka yang valid dan nonnegatif; panjang/lebar ruas harus positif.':return english+' must be a valid nonnegative number; road length and width must be positive.'
        if value=='Kode '+label+' tidak valid.':return 'Invalid code for '+english+'.'
    return value
